// Build the list of domains worth learning, busiest first. A domain only
// counts when something actually evidenced it — a v1 domain was built out of
// company_name and is not evidence of anything.
const MAX_DOMAINS_PER_RUN = 25;
const RELEARN_EVERYTHING = false;   // true re-learns domains already stored

const ne = (v) => v !== undefined && v !== null && String(v).trim() !== '';
const clean = (d) => String(d || '').toLowerCase().trim()
  .replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').replace(/[^a-z0-9.\-]/g, '');
const hostOf = (u) => { const m = String(u || '').match(/^[a-zA-Z][a-zA-Z0-9+.\-]*:\/\/([^\/?#:]+)/); return m ? m[1].replace(/^www\./i, '').toLowerCase() : ''; };

// Domains already in the store, so we do not pay for them twice.
const known = new Set();
try {
  for (const p of $('Read Domain Patterns').all()) {
    const d = clean(p.json.domain);
    const st = String(p.json.pattern_status || '').toLowerCase();
    // 'insufficient' is worth another look once the finder has added more
    // evidence. 'learned' and 'conflicted' are settled for now.
    if (d && (st === 'learned' || st === 'conflicted')) known.add(d);
  }
} catch (e) {}

const EVIDENCED = /firecrawl|search|site_scrape|scrape_verified|_verified|manual|reused/i;

// Never learn or apply a pattern for a mailbox provider. gmail.com turned up
// in the first run with 2 leads on it.
const FREE_MAIL = new Set(['gmail.com','googlemail.com','yahoo.com','ymail.com','hotmail.com','outlook.com','live.com','msn.com','aol.com','icloud.com','me.com','mac.com','protonmail.com','proton.me','gmx.com','mail.com','zoho.com','yandex.com','comcast.net','verizon.net','att.net','sbcglobal.net','bellsouth.net','cox.net','charter.net','earthlink.net']);

// Lead Pool stores credentials in the name field: cut at the first comma.
const cleanName = (n) => String(n || '').split(',')[0]
  .replace(/\([^)]*\)/g, ' ')
  .replace(/\b(dr|rev|minister|bishop|mr|mrs|ms|prof|sr|jr)\.?\s+/gi, ' ')
  .replace(/[^A-Za-zÀ-ɏ\s'\-]/g, ' ').replace(/\s+/g, ' ').trim();

const byDomain = new Map();

for (const item of $input.all()) {
  const r = item.json;
  let dom = '';

  // Strongest first: the host of a page we actually read an address off.
  if (ne(r.email_source_url)) dom = hostOf(r.email_source_url);

  // Then an address whose provenance says someone observed it.
  if (!dom && ne(r.email) && EVIDENCED.test(String(r.email_source || ''))) {
    dom = clean(String(r.email).split('@')[1] || '');
  }

  // Then a company_domain that an evidenced source wrote.
  if (!dom && ne(r.company_domain) && EVIDENCED.test(String(r.company_domain_source || ''))) {
    dom = clean(r.company_domain);
  }

  if (!dom || !dom.includes('.')) continue;
  if (FREE_MAIL.has(dom)) continue;

  if (!byDomain.has(dom)) byDomain.set(dom, { domain: dom, org_sample: String(r.company_name || '').trim(), leads_at_domain: 0, seed_pairs: [] });
  const e = byDomain.get(dom);
  e.leads_at_domain += 1;
  if (!e.org_sample && ne(r.company_name)) e.org_sample = String(r.company_name).trim();

  // Free evidence: an address the finder already read off a page, with the
  // person's name beside it, is a confirmed pair. Seed it rather than paying
  // for a search to rediscover what we already know.
  if (ne(r.email) && EVIDENCED.test(String(r.email_source || ''))) {
    const em = String(r.email).trim();
    if ((em.split('@')[1] || '').toLowerCase() === dom) {
      const person = cleanName(r.name);
      if (person.split(' ').filter(Boolean).length >= 2) e.seed_pairs.push(person + '|' + em);
    }
  }
}

// Fold in every pair the finder banked while it was already searching these
// sites. These cost nothing - the request was paid for by the finder, which
// used to see a whole staff directory and bin everything except our lead.
let harvested = 0;
try {
  for (const h of $('Read Observed Addresses').all()) {
    const d = clean(h.json.domain);
    if (!d || !byDomain.has(d)) continue;
    const nm = String(h.json.person_name || '').trim();
    const em = String(h.json.email || '').trim();
    if (!nm || !em) continue;
    const e = byDomain.get(d);
    const sig = nm + '|' + em;
    if (e.seed_pairs.indexOf(sig) === -1) { e.seed_pairs.push(sig); harvested++; }
  }
} catch (err) {}
console.log('Pairs folded in from the finder harvest: ' + harvested);

for (const e of byDomain.values()) e.pair_count = e.seed_pairs.length;

let domains = Array.from(byDomain.values());
const beforeFilter = domains.length;
if (!RELEARN_EVERYTHING) domains = domains.filter(d => !known.has(d.domain));

// Busiest domains first — that is where a learned format pays for itself.
domains.sort((a, b) => b.leads_at_domain - a.leads_at_domain);

console.log('Evidenced domains found: ' + beforeFilter + ', already learned: ' + known.size + ', to learn now: ' + Math.min(domains.length, MAX_DOMAINS_PER_RUN));
console.log('Domains already holding 2+ pairs before any search: ' + domains.filter(d => d.pair_count >= 2).length);
console.log('Top of queue: ' + domains.slice(0, 10).map(d => d.domain + '(' + d.leads_at_domain + ')').join(', '));

return domains.slice(0, MAX_DOMAINS_PER_RUN).map(d => ({ json: d }));

// Work out how this organisation builds addresses, from any name+address
// pairs on its own site. The lead's own address is not required.
//
// Pairs are NOT matched by proximity. Every name found is tested against every
// address found, and a pair is accepted only when the local part can actually
// be DERIVED from that name. That makes the match self-validating: the thing
// that proves the pair is the same thing that names the format.
const dom = $('Loop Over Domains').item.json;
const res = $json || {};
const now = new Date().toISOString();
const domain = String(dom.domain || '').toLowerCase();

const web = (res.data && Array.isArray(res.data.web)) ? res.data.web
  : (Array.isArray(res.data) ? res.data : []);

const base = {
  domain: domain,
  org_sample: dom.org_sample || '',
  leads_at_domain: dom.leads_at_domain || 0,
  learned_at: now
};

const seeds = Array.isArray(dom.seed_pairs) ? dom.seed_pairs : [];

// Only give up when the search produced nothing AND we hold no pairs already.
if ((res.error || !web.length) && !seeds.length) {
  let msg = res.error ? 'search error' : 'search returned zero results';
  try { if (res.error) msg += ': ' + (typeof res.error === 'string' ? res.error : JSON.stringify(res.error)).slice(0, 250); } catch (e) {}
  return { json: Object.assign({}, base, { pattern: '', pattern_status: res.error ? 'search_error' : 'no_results', agreeing_pairs: 0, total_pairs: 0, conflicting_patterns: '', sample_pairs: '', source_urls: '', notes: msg }) };
}

const EMAIL_RE = /[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/g;
// Two or three capitalised words, optionally with a middle initial.
const NAME_RE = /\b([A-Z][a-z]{1,15})\s+(?:[A-Z]\.?\s+)?([A-Z][a-zA-Z'\-]{1,20})\b/g;
const ROLE_LOCALS = new Set(['info','admin','administrator','contact','support','hello','office','mail','team','sales','billing','help','webmaster','postmaster','enquiries','inquiries','general','donations','volunteer','assistance','press','media','marketing','hr','careers','jobs','service','services','reception','secretary','accounts','finance','legal','privacy','abuse','security','feedback','subscribe','newsletter','communications','development','grants','outreach','clerk','cityhall','planning','ecdev','econdev','economicdevelopment','citycouncil','council','commdev','records','permits','utilities','court','library','museum','parks','police','fire','water','sewer','ticket','tickets','events','info1','mailbox']);
// Words that look like names but are page furniture.
const NOT_A_NAME = new Set(['staff','directory','contact','city','town','county','department','office','email','phone','main','street','road','avenue','suite','public','works','human','resources','economic','community','development','police','fire','parks','recreation','skip','main','content','read','more','view','all','site','map','privacy','policy','terms','use','home','page','search','menu','close','open','click','here','learn','copyright','rights','reserved','government','services','business','residents','how','do','i','quick','links','records','division','board','committee','center','centre','foundation','church','temple','synagogue','school','university','college','hospital','clinic','district','authority','commission','association','society','institute','trust','fund','group','team','staff1','our','people','meet','about']);

function normalise(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]/g, ''); }

// Every way an organisation might build a local part from a name.
function formatsFor(first, last) {
  const f = first[0], l = last[0];
  return [
    ['{f}{last}', f + last],
    ['{first}.{last}', first + '.' + last],
    ['{first}{last}', first + last],
    ['{f}.{last}', f + '.' + last],
    ['{first}_{last}', first + '_' + last],
    ['{first}-{last}', first + '-' + last],
    ['{first}{l}', first + l],
    ['{last}{f}', last + f],
    ['{last}.{first}', last + '.' + first],
    ['{last}{first}', last + first],
    ['{first}', first],
    ['{last}', last],
    ['{f}{l}', f + l]
  ];
}

// ---------- harvest ----------
const emails = new Map();   // lower email -> {email, local, url}
const names = new Map();    // 'first last' -> {first, last}
const urls = new Set();

// Seed with pairs the finder already proved, before looking at search results.
for (const sp of seeds) {
  const bits = String(sp).split('|');
  const nm = (bits[0] || '').trim(), em = (bits[1] || '').trim();
  if (!nm || !em) continue;
  const lower = em.toLowerCase();
  if (!emails.has(lower)) emails.set(lower, { email: em, local: lower.split('@')[0] || '', url: 'lead_pool:already_observed' });
  const p = nm.toLowerCase().split(/\s+/).filter(Boolean);
  if (p.length >= 2) names.set(p[0] + ' ' + p[p.length - 1], { first: p[0], last: p[p.length - 1] });
}

for (const r of web) {
  const url = r.url || '';
  const text = [r.title, r.description, r.snippet, r.markdown].filter(Boolean).join(' \n ');
  if (!text) continue;

  const foundEmails = text.match(EMAIL_RE) || [];
  for (const raw of foundEmails) {
    const em = raw.replace(/[.,;:)\]]+$/, '');
    const lower = em.toLowerCase();
    const local = lower.split('@')[0] || '';
    const d = lower.split('@')[1] || '';
    if (d !== domain && !d.endsWith('.' + domain)) continue;   // only this org's own addresses
    if (ROLE_LOCALS.has(local)) continue;                      // role boxes teach nothing
    if (!emails.has(lower)) { emails.set(lower, { email: em, local: local, url: url }); urls.add(url); }
  }

  let m;
  NAME_RE.lastIndex = 0;
  while ((m = NAME_RE.exec(text)) !== null) {
    const first = m[1].toLowerCase(), last = m[2].toLowerCase();
    if (NOT_A_NAME.has(first) || NOT_A_NAME.has(last)) continue;
    if (first.length < 2 || last.length < 2) continue;
    names.set(first + ' ' + last, { first: first, last: last });
  }
}

// ---------- pair by derivability ----------
const tally = {};
const accepted = [];

for (const [lower, e] of emails) {
  const localNorm = normalise(e.local);
  let hit = null;
  for (const [key, n] of names) {
    for (const [label, built] of formatsFor(n.first, n.last)) {
      // Compare normalised so '{first}.{last}' and '{first}{last}' do not
      // collide: check the raw local part first, then the normalised one.
      if (e.local.toLowerCase() === built) { hit = { label: label, name: key }; break; }
      if (!hit && localNorm === normalise(built) && label.indexOf('.') === -1 && label.indexOf('_') === -1 && label.indexOf('-') === -1) { hit = { label: label, name: key }; }
    }
    if (hit && hit.exact !== false) break;
  }
  if (!hit) continue;
  // A bare '{first}' or '{last}' is too weak to establish a house style on its
  // own; count it but never let it win.
  tally[hit.label] = (tally[hit.label] || 0) + 1;
  accepted.push(hit.name + '=' + e.email);
}

const WEAK = new Set(['{first}', '{last}', '{f}{l}']);
const ranked = Object.keys(tally).sort((a, b) => {
  const wa = WEAK.has(a) ? 1 : 0, wb = WEAK.has(b) ? 1 : 0;
  if (wa !== wb) return wa - wb;
  return tally[b] - tally[a];
});

const total = accepted.length;
const best = ranked[0] || '';
const agreeing = best ? tally[best] : 0;
const conflicts = ranked.slice(1).map(k => k + ':' + tally[k]).join(', ');

let status;
if (total === 0) status = 'no_pairs';
else if (agreeing < 2) status = 'insufficient';
else if (agreeing / total < 0.6) status = 'conflicted';
// '{first}' is normally too weak to call a house style, but Temple Beth Am
// returned 7 of 8 pairs on it (davida@, reyna@, jacob@...). At that weight of
// agreement it is the format, not a coincidence.
else if (WEAK.has(best) && !(agreeing >= 4 && agreeing / total >= 0.8)) status = 'conflicted';
else status = 'learned';

return { json: Object.assign({}, base, {
  pattern: status === 'learned' ? best : '',
  pattern_status: status,
  agreeing_pairs: agreeing,
  total_pairs: total,
  conflicting_patterns: conflicts,
  sample_pairs: accepted.slice(0, 8).join('; ').slice(0, 450),
  source_urls: Array.from(urls).slice(0, 4).join(' | ').slice(0, 450),
  notes: status === 'learned' ? '' : ('emails seen: ' + emails.size + ', names seen: ' + names.size + ', pairs: ' + total)
}) };

// Learn Pattern runs inside the batch loop, so $(...).all() returns only the
// last batch. Walk every run index for the true total.
let rows = [];
for (let r = 0; r < 2000; r++) {
  let batch;
  try { batch = $('Learn Pattern').all(0, r); } catch (e) { break; }
  if (!batch || batch.length === 0) break;
  rows.push(...batch.map(i => i.json));
}

const tally = {};
for (const r of rows) {
  const k = r.pattern_status || 'unknown';
  tally[k] = (tally[k] || 0) + 1;
}

const learned = rows.filter(r => r.pattern_status === 'learned')
  .sort((a, b) => (b.leads_at_domain || 0) - (a.leads_at_domain || 0))
  .map(r => ({ domain: r.domain, pattern: r.pattern, from_pairs: r.agreeing_pairs + '/' + r.total_pairs, leads_this_unlocks: r.leads_at_domain }));

const leadsUnlocked = learned.reduce((n, r) => n + (r.leads_this_unlocks || 0), 0);

return [{ json: {
  run_id: $execution.id,
  finished_at: new Date().toISOString(),
  domains_examined: rows.length,
  by_status: tally,
  patterns_learned: learned.length,
  leads_these_patterns_cover: leadsUnlocked,
  learned: learned
}}];
